public class MainActivity extends Activity {
    private static final int BACKUP=10, RESTORE=11, SAVE_PDF=12, SAVE_XLSX=13, PICK_BILL=14;
    private final int green=Color.rgb(25,61,52), gold=Color.rgb(177,139,76), ink=Color.rgb(35,45,40);
    private Store store; private LinearLayout root, list; private long activeCustomer, editingPurchase;
    private String pdfMode="save", pickedBill="", purchaseQuery=""; private Uri pendingPdf;
    private EditText dateFrom,dateTo;

    @Override public void onCreate(Bundle b){super.onCreate(b);store=new Store(this);showHome();}
    private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,6,0,6);return t;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(18,14,18,20);return l;}
    private Button button(String value){Button b=new Button(this);b.setText(value);b.setAllCaps(false);return b;}
    private void shell(String title){
        root=column();root.setBackgroundColor(Color.rgb(248,247,243));ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);
        LinearLayout banner=new LinearLayout(this);banner.setOrientation(1);banner.setGravity(Gravity.CENTER);banner.setPadding(18,20,18,18);
        GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{green,Color.rgb(42,83,69)});bg.setCornerRadius(24);banner.setBackground(bg);
        TextView brand=text("SEN BROS",30,Color.WHITE);brand.setTypeface(null,1);brand.setGravity(Gravity.CENTER);brand.setLetterSpacing(.08f);banner.addView(brand);
        TextView app=text("CUSTOMER BOOK",22,Color.rgb(239,217,176));app.setTypeface(null,1);app.setGravity(Gravity.CENTER);app.setLetterSpacing(.12f);banner.addView(app);
        TextView heading=text(title,22,green);heading.setTypeface(null,1);heading.setPadding(2,18,2,8);root.addView(banner);root.addView(heading);
    }
    private void showHome(){
        shell("Customers");root.addView(text("Customer records and purchase history",14,ink));
        Button add=button("＋  Add customer");root.addView(add);add.setOnClickListener(v->customerForm(0));
        LinearLayout tools=new LinearLayout(this);tools.setOrientation(LinearLayout.HORIZONTAL);
        Button backup=button("Back up to Drive");Button restore=button("Restore backup");tools.addView(backup,new LinearLayout.LayoutParams(0,-2,1));tools.addView(restore,new LinearLayout.LayoutParams(0,-2,1));root.addView(tools);
        backup.setOnClickListener(v->createDocument(BACKUP,"application/json","SenBros-backup.json"));restore.setOnClickListener(v->openDocument(RESTORE,"application/json"));
        Button excel=button("Export Excel workbook");root.addView(excel);excel.setOnClickListener(v->createDocument(SAVE_XLSX,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","SenBros-customers.xlsx"));
        EditText search=new EditText(this);search.setSingleLine();search.setHint("Search name, code, phone or email");root.addView(search);
        list=column();list.setPadding(0,6,0,0);root.addView(list);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){loadCustomers(s.toString());}public void afterTextChanged(android.text.Editable e){}});loadCustomers("");
    }
    private void loadCustomers(String query){
        if(list==null)return;list.removeAllViews();String like="%"+query+"%";
        Cursor c=store.getReadableDatabase().rawQuery("SELECT id,code,name,phone FROM customers WHERE name LIKE ? OR code LIKE ? OR phone LIKE ? OR email LIKE ? ORDER BY name",new String[]{like,like,like,like});
        while(c.moveToNext()){long id=c.getLong(0);LinearLayout card=column();card.setPadding(14,9,14,10);card.setBackgroundColor(Color.WHITE);TextView name=text(c.getString(2),18,green);name.setTypeface(null,1);card.addView(name);card.addView(text(c.getString(1)+"  ·  "+c.getString(3),13,ink));Button open=button("Open customer");card.addView(open);open.setOnClickListener(v->{purchaseQuery="";showCustomer(id,"","");});list.addView(card);}
        c.close();if(list.getChildCount()==0)list.addView(text("No matching customers. Add a customer to get started.",15,ink));
    }
    private EditText field(String hint,String value){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);if(value!=null)e.setText(value);return e;}
    private String val(EditText e){return e.getText().toString().trim();}
    private String blank(String s){return s==null||s.trim().isEmpty()?"—":s;}
    private void customerForm(long id){
        String[] old={"","","","",""};String code="";
        if(id!=0){Cursor c=store.getReadableDatabase().rawQuery("SELECT code,name,address,phone,alt,email FROM customers WHERE id=?",new String[]{""+id});if(c.moveToFirst()){code=c.getString(0);for(int i=0;i<5;i++)old[i]=blankForEdit(c.getString(i+1));}c.close();}
        LinearLayout f=column();EditText name=field("Full name *",old[0]),address=field("Address",old[1]),phone=field("Phone number *",old[2]),alt=field("Alternate phone",old[3]),email=field("Email",old[4]);for(EditText e:new EditText[]{name,address,phone,alt,email})f.addView(e);
        String title=id==0?"New customer":"Edit customer · "+code;
        new AlertDialog.Builder(this).setTitle(title).setView(f).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{if(val(name).isEmpty()||val(phone).isEmpty()){toast("Name and phone are required");return;}if(id==0){String newCode=store.addCustomer(val(name),val(address),val(phone),val(alt),val(email));toast("Saved as "+newCode);showHome();}else{store.updateCustomer(id,val(name),val(address),val(phone),val(alt),val(email));showCustomer(id,"","");}}).show();
    }
    private String blankForEdit(String s){return s==null?"":s;}
    private void showCustomer(long id,String from,String to){
        activeCustomer=id;Cursor c=store.getReadableDatabase().rawQuery("SELECT code,name,address,phone,alt,email FROM customers WHERE id=?",new String[]{""+id});if(!c.moveToFirst()){c.close();return;}
        String code=c.getString(0),name=c.getString(1);String details="Code: "+code+"\nAddress: "+blank(c.getString(2))+"\nPhone: "+blank(c.getString(3))+"\nAlternate phone: "+blank(c.getString(4))+"\nEmail: "+blank(c.getString(5));c.close();shell(name);root.addView(text(details,14,ink));
        Button edit=button("Edit customer details");root.addView(edit);edit.setOnClickListener(v->customerForm(id));
        root.addView(text("Filter purchases by date (YYYY-MM-DD)",15,green));LinearLayout dates=new LinearLayout(this);dates.setOrientation(LinearLayout.HORIZONTAL);dateFrom=field("From date",from);dateTo=field("To date",to);dates.addView(dateFrom,new LinearLayout.LayoutParams(0,-2,1));dates.addView(dateTo,new LinearLayout.LayoutParams(0,-2,1));root.addView(dates);
        Button filter=button("Apply date filter");root.addView(filter);filter.setOnClickListener(v->showCustomer(id,val(dateFrom),val(dateTo)));
        root.addView(text("Purchase history",20,green));EditText searchPurchases=field("Search item, category or notes",purchaseQuery);root.addView(searchPurchases);
        Button apply=button("Apply search & date filter");root.addView(apply);apply.setOnClickListener(v->{purchaseQuery=val(searchPurchases);showCustomer(id,val(dateFrom),val(dateTo));});
        list=column();list.setPadding(0,2,0,0);root.addView(list);String sql="SELECT id,date,item,category,quantity,price,payment,paid,notes,bill_uri FROM purchases WHERE customer_id=?";ArrayList<String> args=new ArrayList<>();args.add(""+id);if(!from.isEmpty()){sql+=" AND date>=?";args.add(from);}if(!to.isEmpty()){sql+=" AND date<=?";args.add(to);}if(!purchaseQuery.isEmpty()){sql+=" AND (item LIKE ? OR category LIKE ? OR notes LIKE ?)";String pattern="%"+purchaseQuery+"%";args.add(pattern);args.add(pattern);args.add(pattern);}sql+=" ORDER BY date DESC,id DESC";
        Cursor p=store.getReadableDatabase().rawQuery(sql,args.toArray(new String[0]));double total=0;
        while(p.moveToNext()){long pid=p.getLong(0);double line=p.getDouble(4)*p.getDouble(5);total+=line;LinearLayout card=column();card.setPadding(12,8,12,8);card.setBackgroundColor(Color.WHITE);
            card.addView(text(p.getString(1)+"  ·  "+p.getString(3),15,green));card.addView(text(p.getString(2)+"\nQty "+p.getString(4)+" × ₹"+p.getString(5)+" = ₹"+String.format(Locale.US,"%.2f",line)+"\nPayment: "+blank(p.getString(6))+" · Paid ₹"+p.getString(7)+"\nNotes: "+blank(p.getString(8)),14,ink));
            LinearLayout actions=new LinearLayout(this);Button change=button("Edit purchase");actions.addView(change);change.setOnClickListener(v->purchaseForm(id,pid));if(p.getString(9)!=null&&!p.getString(9).isEmpty()){Button bill=button("Open bill scan");actions.addView(bill);String uri=p.getString(9);bill.setOnClickListener(v->openBill(uri));}card.addView(actions);listCard(card);
        }
        p.close();root.addView(text("Filtered purchase total: ₹"+String.format(Locale.US,"%.2f",total),17,green));
        Button add=button("＋  Add purchase");root.addView(add);add.setOnClickListener(v->purchaseForm(id,0));
        Button savePdf=button("Save PDF");root.addView(savePdf);savePdf.setOnClickListener(v->{activeCustomer=id;pdfMode="save";createDocument(SAVE_PDF,"application/pdf",code+"-statement.pdf");});
        Button sharePdf=button("Share PDF");root.addView(sharePdf);sharePdf.setOnClickListener(v->{activeCustomer=id;pdfMode="share";createDocument(SAVE_PDF,"application/pdf",code+"-statement.pdf");});
        Button printPdf=button("Print PDF");root.addView(printPdf);printPdf.setOnClickListener(v->{activeCustomer=id;pdfMode="print";createDocument(SAVE_PDF,"application/pdf",code+"-statement.pdf");});
        Button back=button("←  All customers");root.addView(back);back.setOnClickListener(v->showHome());
    }
    private void listCard(View v){list.addView(v);View gap=new View(this);gap.setLayoutParams(new LinearLayout.LayoutParams(1,8));list.addView(gap);}
    private void purchaseForm(long customer,long purchase){
        editingPurchase=purchase;pickedBill="";String[] x={"","","","1","0","","0","",""};
        if(purchase!=0){Cursor c=store.getReadableDatabase().rawQuery("SELECT date,item,category,quantity,price,payment,paid,notes,bill_uri FROM purchases WHERE id=?",new String[]{""+purchase});if(c.moveToFirst()){for(int i=0;i<9;i++)x[i]=blankForEdit(c.getString(i));pickedBill=x[8];}c.close();}else x[0]=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());
        LinearLayout f=column();EditText date=field("Date (YYYY-MM-DD)",x[0]),item=field("Item / description *",x[1]),category=field("Product category",x[2]),qty=field("Quantity",x[3]),price=field("Unit price (₹)",x[4]),payment=field("Payment details (cash, UPI, card...)",x[5]),paid=field("Amount paid (₹)",x[6]),notes=field("Notes",x[7]);
        for(EditText e:new EditText[]{date,item,category,qty,price,payment,paid,notes})f.addView(e);
        Button attach=button(pickedBill.isEmpty()?"Attach bill scan from Google Drive":"Bill scan attached · change");f.addView(attach);attach.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/*"});startActivityForResult(i,PICK_BILL);});
        new AlertDialog.Builder(this).setTitle(purchase==0?"Add purchase":"Edit purchase").setView(f).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{if(val(item).isEmpty())throw new Exception();double q=Double.parseDouble(or(val(qty),"1")),pr=Double.parseDouble(or(val(price),"0")),amount=Double.parseDouble(or(val(paid),"0"));if(purchase==0)store.addPurchase(customer,val(date),val(item),val(category),q,pr,val(payment),amount,val(notes),pickedBill);else store.updatePurchase(purchase,val(date),val(item),val(category),q,pr,val(payment),amount,val(notes),pickedBill);showCustomer(customer,"","");}catch(Exception ex){toast("Enter an item and valid quantity, price and amount");}}).show();
    }
    private String or(String value,String fallback){return value.isEmpty()?fallback:value;}
    private void createDocument(int request,String mime,String title){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,title);startActivityForResult(i,request);}
    private void openDocument(int request,String mime){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);startActivityForResult(i,request);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null)return;
        try{if(request==BACKUP){writeBackup(uri);toast("Backup saved. Choose Google Drive in the save screen to store it there.");}else if(request==RESTORE){new AlertDialog.Builder(this).setTitle("Replace customer records?").setMessage("Restoring this backup replaces the customer and purchase records currently on this phone.").setNegativeButton("Cancel",null).setPositiveButton("Restore",(dialog,which)->{try{restoreBackup(uri);showHome();toast("Backup restored");}catch(Exception e){toast("Could not restore backup: "+e.getMessage());}}).show();}else if(request==SAVE_XLSX){writeWorkbook(uri);toast("Excel workbook saved");}else if(request==SAVE_PDF){pendingPdf=uri;byte[] bytes=makePdf(activeCustomer);try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(bytes);}if("share".equals(pdfMode))sharePdf(uri);else if("print".equals(pdfMode))printPdf(uri);else toast("PDF saved");}else if(request==PICK_BILL){try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(Exception ignored){}pickedBill=uri.toString();toast("Bill attached. Save the purchase to keep it.");}}
        catch(Exception e){toast("Could not complete that action: "+e.getMessage());}}
    private void sharePdf(Uri uri){Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/pdf");i.putExtra(Intent.EXTRA_STREAM,uri);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Share customer PDF"));}
    private void printPdf(Uri uri){PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("Sen Bros customer statement",new PrintDocumentAdapter(){public void onLayout(PrintAttributes oldA,PrintAttributes newA,CancellationSignal signal,LayoutResultCallback cb,Bundle extras){if(!signal.isCanceled())cb.onLayoutFinished(new PrintDocumentInfo.Builder("customer-statement.pdf").setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).setPageCount(PrintDocumentInfo.PAGE_COUNT_UNKNOWN).build(),true);}public void onWrite(PageRange[] pages,ParcelFileDescriptor dest,CancellationSignal signal,WriteResultCallback cb){try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(dest.getFileDescriptor())){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0){if(signal.isCanceled()){cb.onWriteCancelled();return;}out.write(buf,0,n);}cb.onWriteFinished(new PageRange[]{PageRange.ALL_PAGES});}catch(Exception e){cb.onWriteFailed(e.getMessage());}}},new PrintAttributes.Builder().build());}
    private void openBill(String s){try{Uri u=Uri.parse(s);Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(u,"*/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){toast("Could not open the bill file");}}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}

    private byte[] makePdf(long customer)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas canvas=page.getCanvas();Paint p=new Paint(3);p.setColor(green);p.setTextSize(19);canvas.drawText("SEN BROS GUINEA PALACE",40,45,p);p.setTextSize(15);canvas.drawText("Customer & Purchase Statement",40,72,p);p.setColor(ink);p.setTextSize(10);int y=98;
        Cursor c=store.getReadableDatabase().rawQuery("SELECT code,name,address,phone,alt,email FROM customers WHERE id=?",new String[]{""+customer});if(c.moveToFirst()){String[] rows={"Code: "+c.getString(0),"Name: "+c.getString(1),"Address: "+blank(c.getString(2)),"Phone: "+blank(c.getString(3)),"Alternate phone: "+blank(c.getString(4)),"Email: "+blank(c.getString(5))};for(String row:rows){canvas.drawText(row,40,y,p);y+=17;}}c.close();y+=12;
        Cursor q=store.getReadableDatabase().rawQuery("SELECT date,item,category,quantity,price,payment,paid,notes FROM purchases WHERE customer_id=? ORDER BY date,id",new String[]{""+customer});p.setFakeBoldText(true);canvas.drawText("Date",40,y,p);canvas.drawText("Item / category",120,y,p);canvas.drawText("Qty",340,y,p);canvas.drawText("Unit",390,y,p);canvas.drawText("Total",475,y,p);p.setFakeBoldText(false);y+=12;canvas.drawLine(40,y,555,y,p);y+=17;
        while(q.moveToNext()){if(y>770){pdf.finishPage(page);page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,pdf.getPages().size()+1).create());canvas=page.getCanvas();y=48;}String item=q.getString(1)+(blank(q.getString(2)).equals("—")?"":" / "+q.getString(2));if(item.length()>31)item=item.substring(0,28)+"...";canvas.drawText(q.getString(0),40,y,p);canvas.drawText(item,120,y,p);canvas.drawText(q.getString(3),340,y,p);canvas.drawText(String.format(Locale.US,"%.2f",q.getDouble(4)),390,y,p);canvas.drawText(String.format(Locale.US,"%.2f",q.getDouble(3)*q.getDouble(4)),475,y,p);y+=15;canvas.drawText("Payment: "+blank(q.getString(5))+" | Paid ₹"+q.getString(6)+" | Notes: "+blank(q.getString(7)),120,y,p);y+=22;}q.close();pdf.finishPage(page);pdf.writeTo(bytes);pdf.close();return bytes.toByteArray();}

    private void writeBackup(Uri uri)throws Exception{JSONObject data=new JSONObject();JSONArray customers=new JSONArray(),purchases=new JSONArray();SQLiteDatabase db=store.getReadableDatabase();Cursor c=db.rawQuery("SELECT id,code,name,address,phone,alt,email FROM customers ORDER BY id",null);String[] ck={"id","code","name","address","phone","alt","email"};while(c.moveToNext()){JSONObject o=new JSONObject();for(int i=0;i<ck.length;i++)o.put(ck[i],c.getString(i));customers.put(o);}c.close();Cursor p=db.rawQuery("SELECT id,customer_id,date,item,category,quantity,price,payment,paid,notes,bill_uri FROM purchases ORDER BY id",null);String[] pk={"id","customer_id","date","item","category","quantity","price","payment","paid","notes","bill_uri"};while(p.moveToNext()){JSONObject o=new JSONObject();for(int i=0;i<pk.length;i++)o.put(pk[i],p.getString(i));purchases.put(o);}p.close();data.put("format","senbros-customer-book");data.put("version",2);data.put("customers",customers);data.put("purchases",purchases);try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(data.toString(2).getBytes("UTF-8"));}}
    private void restoreBackup(Uri uri)throws Exception{StringBuilder s=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(uri),"UTF-8"))){String line;while((line=r.readLine())!=null)s.append(line);}JSONObject data=new JSONObject(s.toString());if(!"senbros-customer-book".equals(data.optString("format")))throw new Exception("This is not a Sen Bros backup");SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{db.delete("purchases",null,null);db.delete("customers",null,null);JSONArray cs=data.getJSONArray("customers");for(int i=0;i<cs.length();i++){JSONObject o=cs.getJSONObject(i);ContentValues v=new ContentValues();for(String k:new String[]{"id","code","name","address","phone","alt","email"})if(!o.isNull(k))v.put(k,o.optString(k));db.insertOrThrow("customers",null,v);}JSONArray ps=data.getJSONArray("purchases");for(int i=0;i<ps.length();i++){JSONObject o=ps.getJSONObject(i);ContentValues v=new ContentValues();for(String k:new String[]{"id","customer_id","date","item","category","payment","notes","bill_uri"})if(!o.isNull(k))v.put(k,o.optString(k));for(String k:new String[]{"quantity","price","paid"})if(!o.isNull(k))v.put(k,o.optDouble(k));db.insertOrThrow("purchases",null,v);}db.setTransactionSuccessful();}finally{db.endTransaction();}}

    private void writeWorkbook(Uri uri)throws Exception{try(ZipOutputStream z=new ZipOutputStream(getContentResolver().openOutputStream(uri))){put(z,"[Content_Types].xml","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet2.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");put(z,"_rels/.rels","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");put(z,"xl/workbook.xml","<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Customers\" sheetId=\"1\" r:id=\"rId1\"/><sheet name=\"Purchases\" sheetId=\"2\" r:id=\"rId2\"/></sheets></workbook>");put(z,"xl/_rels/workbook.xml.rels","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet2.xml\"/></Relationships>");
        ArrayList<String[]> rows=new ArrayList<>();rows.add(new String[]{"Customer code","Name","Address","Phone","Alternate phone","Email"});Cursor c=store.getReadableDatabase().rawQuery("SELECT code,name,address,phone,alt,email FROM customers ORDER BY name",null);while(c.moveToNext())rows.add(new String[]{c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getString(5)});c.close();put(z,"xl/worksheets/sheet1.xml",sheet(rows));
        rows.clear();rows.add(new String[]{"Customer code","Date","Item","Category","Quantity","Unit price","Line total","Payment details","Paid","Notes","Bill scan URI"});Cursor p=store.getReadableDatabase().rawQuery("SELECT c.code,p.date,p.item,p.category,p.quantity,p.price,p.payment,p.paid,p.notes,p.bill_uri FROM purchases p JOIN customers c ON c.id=p.customer_id ORDER BY p.date",null);while(p.moveToNext())rows.add(new String[]{p.getString(0),p.getString(1),p.getString(2),p.getString(3),p.getString(4),p.getString(5),String.format(Locale.US,"%.2f",p.getDouble(4)*p.getDouble(5)),p.getString(6),p.getString(7),p.getString(8),p.getString(9)});p.close();put(z,"xl/worksheets/sheet2.xml",sheet(rows));}}
    private String sheet(ArrayList<String[]> rows){StringBuilder x=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>");for(int r=0;r<rows.size();r++){x.append("<row r=\"").append(r+1).append("\">");for(int c=0;c<rows.get(r).length;c++){String ref=columnName(c+1)+(r+1);x.append("<c r=\"").append(ref).append("\" t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(xml(rows.get(r)[c])).append("</t></is></c>");}x.append("</row>");}return x.append("</sheetData></worksheet>").toString();}
    private String columnName(int n){StringBuilder s=new StringBuilder();while(n>0){int r=(n-1)%26;s.insert(0,(char)('A'+r));n=(n-1)/26;}return s.toString();}
    private String xml(String s){if(s==null)return "";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
    private void put(ZipOutputStream z,String name,String value)throws Exception{z.putNextEntry(new ZipEntry(name));z.write(value.getBytes("UTF-8"));z.closeEntry();}

    private static class Store extends SQLiteOpenHelper{
        Store(Context c){super(c,"senbros_customers.db",null,2);}
        public void onConfigure(SQLiteDatabase db){db.setForeignKeyConstraintsEnabled(true);}
        public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE customers(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,name TEXT NOT NULL,address TEXT,phone TEXT NOT NULL,alt TEXT,email TEXT)");db.execSQL("CREATE TABLE purchases(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER NOT NULL,date TEXT,item TEXT NOT NULL,category TEXT,quantity REAL,price REAL,payment TEXT,paid REAL,notes TEXT,bill_uri TEXT,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE)");}
        public void onUpgrade(SQLiteDatabase db,int old,int now){if(old<2){db.execSQL("ALTER TABLE purchases ADD COLUMN category TEXT");db.execSQL("ALTER TABLE purchases ADD COLUMN notes TEXT");db.execSQL("ALTER TABLE purchases ADD COLUMN bill_uri TEXT");}}
        String addCustomer(String name,String address,String phone,String alt,String email){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("name",name);v.put("address",address);v.put("phone",phone);v.put("alt",alt);v.put("email",email);long id=db.insertOrThrow("customers",null,v);String code=String.format(Locale.US,"SBGP-%06d",id);ContentValues u=new ContentValues();u.put("code",code);db.update("customers",u,"id=?",new String[]{""+id});db.setTransactionSuccessful();return code;}finally{db.endTransaction();}}
        void updateCustomer(long id,String name,String address,String phone,String alt,String email){ContentValues v=new ContentValues();v.put("name",name);v.put("address",address);v.put("phone",phone);v.put("alt",alt);v.put("email",email);getWritableDatabase().update("customers",v,"id=?",new String[]{""+id});}
        void addPurchase(long customer,String date,String item,String category,double qty,double price,String payment,double paid,String notes,String bill){savePurchase(0,customer,date,item,category,qty,price,payment,paid,notes,bill);}
        void updatePurchase(long id,String date,String item,String category,double qty,double price,String payment,double paid,String notes,String bill){savePurchase(id,0,date,item,category,qty,price,payment,paid,notes,bill);}
        void savePurchase(long id,long customer,String date,String item,String category,double qty,double price,String payment,double paid,String notes,String bill){ContentValues v=new ContentValues();if(id==0)v.put("customer_id",customer);v.put("date",date);v.put("item",item);v.put("category",category);v.put("quantity",qty);v.put("price",price);v.put("payment",payment);v.put("paid",paid);v.put("notes",notes);v.put("bill_uri",bill);if(id==0)getWritableDatabase().insertOrThrow("purchases",null,v);else getWritableDatabase().update("purchases",v,"id=?",new String[]{""+id});}
    }
}
